#include "stdlib/lapack/base/dpstf2.h"
#include "validate.h"
#include "panel.h"

/**
* Computes a complete-pivoting Cholesky factorization with alternative indexing.
*
* @param uplo        selected matrix triangle
* @param N           matrix order
* @param A           input/output matrix
* @param strideA1    matrix row stride
* @param strideA2    matrix column stride
* @param offsetA     matrix offset
* @param PIV         complete permutation output
* @param stridePIV   permutation stride
* @param offsetPIV   permutation offset
* @param RANK        rank output
* @param offsetRANK  rank offset
* @param TOL         finite tolerance
* @param WORK        2N-element scratch
* @param strideWORK  scratch stride
* @param offsetWORK  scratch offset
* @return            INFO or a negative argument position
*/
LAPACK_INT API_SUFFIX(c_dpstf2_ndarray)( const LAPACK_UPLO uplo, const LAPACK_INT N, double *A, const LAPACK_INT strideA1, const LAPACK_INT strideA2, const LAPACK_INT offsetA, LAPACK_INT *PIV, const LAPACK_INT stridePIV, const LAPACK_INT offsetPIV, LAPACK_INT *RANK, const LAPACK_INT offsetRANK, const double TOL, double *WORK, const LAPACK_INT strideWORK, const LAPACK_INT offsetWORK ) {
	dpstf2_view a;
	intmax_t pvt;
	intmax_t j;
	intmax_t i;
	LAPACK_INT info;
	LAPACK_INT item;
	double ajj;
	double dstop;
	double temp;
	volatile double product;

	info = dpstf2_validate( 0, uplo, N, A, strideA1, strideA2, offsetA, PIV, stridePIV, offsetPIV, RANK, offsetRANK, TOL, WORK, strideWORK, offsetWORK );
	if ( info != 0 ) return dpstf2_error( "c_dpstf2_ndarray", info );
	if ( N == 0 ) {
		RANK[ offsetRANK ] = 0;
		return 0;
	}
	a.data = A;
	a.stride1 = strideA1;
	a.stride2 = strideA2;
	a.offset = offsetA;
	for ( i = 1; i <= N; i++ ) PIV[ offsetPIV+(i-1)*stridePIV ] = (LAPACK_INT)i;
	pvt = 1;
	ajj = DPSTF2_CELL( &a, 1, 1 );
	for ( i = 2; i <= N; i++ ) {
		if ( DPSTF2_CELL( &a, i, i ) > ajj ) {
			pvt = i;
			ajj = DPSTF2_CELL( &a, pvt, pvt );
		}
	}
	if ( ajj <= 0.0 || isnan( ajj ) ) {
		RANK[ offsetRANK ] = 0;
		return 1;
	}
	product = (double)N*0x1p-53;
	dstop = TOL < 0.0 ? product*ajj : TOL;
	for ( i = 1; i <= N; i++ ) WORK[ offsetWORK+(i-1)*strideWORK ] = 0.0;
	for ( j = 1; j <= N; j++ ) {
		for ( i = j; i <= N; i++ ) {
			if ( j > 1 ) {
				temp = uplo == LAPACK_UPPER_TRIANGLE ? DPSTF2_CELL( &a, j-1, i ) : DPSTF2_CELL( &a, i, j-1 );
				product = temp*temp;
				WORK[ offsetWORK+(i-1)*strideWORK ] += product;
			}
			WORK[ offsetWORK+(N+i-1)*strideWORK ] = DPSTF2_CELL( &a, i, i )-WORK[ offsetWORK+(i-1)*strideWORK ];
		}
		if ( j > 1 ) {
			pvt = j+dpstf2_first_max( N-j+1, WORK, strideWORK, offsetWORK+(N+j-1)*strideWORK );
			ajj = WORK[ offsetWORK+(N+pvt-1)*strideWORK ];
			if ( ajj <= dstop || isnan( ajj ) ) {
				// This reference diagnostic pivot is an observable output on early return.
				// cppcheck-suppress unreadVariable
				DPSTF2_CELL( &a, j, j ) = ajj;
				RANK[ offsetRANK ] = (LAPACK_INT)(j-1);
				return 1;
			}
		}
		if ( j != pvt ) {
			DPSTF2_CELL( &a, pvt, pvt ) = DPSTF2_CELL( &a, j, j );
			if ( uplo == LAPACK_UPPER_TRIANGLE ) {
				dpstf2_swap( j-1, &a, 1, j, 0, 1, pvt, 0 );
				dpstf2_swap( N-pvt, &a, j, pvt+1, 1, pvt, pvt+1, 1 );
				dpstf2_swap( pvt-j-1, &a, j, j+1, 1, j+1, pvt, 0 );
			} else {
				dpstf2_swap( j-1, &a, j, 1, 1, pvt, 1, 1 );
				dpstf2_swap( N-pvt, &a, pvt+1, j, 0, pvt+1, pvt, 0 );
				dpstf2_swap( pvt-j-1, &a, j+1, j, 0, pvt, j+1, 1 );
			}
			temp = WORK[ offsetWORK+(j-1)*strideWORK ];
			WORK[ offsetWORK+(j-1)*strideWORK ] = WORK[ offsetWORK+(pvt-1)*strideWORK ];
			WORK[ offsetWORK+(pvt-1)*strideWORK ] = temp;
			item = PIV[ offsetPIV+(j-1)*stridePIV ];
			PIV[ offsetPIV+(j-1)*stridePIV ] = PIV[ offsetPIV+(pvt-1)*stridePIV ];
			PIV[ offsetPIV+(pvt-1)*stridePIV ] = item;
		}
		ajj = sqrt( ajj );
		DPSTF2_CELL( &a, j, j ) = ajj;
		if ( j < N ) {
			dpstf2_gemv( uplo, N, j, &a );
			if ( uplo == LAPACK_UPPER_TRIANGLE ) dpstf2_scale( N-j, 1.0/ajj, &a, j, j+1, 1 );
			else dpstf2_scale( N-j, 1.0/ajj, &a, j+1, j, 0 );
		}
	}
	RANK[ offsetRANK ] = N;
	return 0;
}
